package grc20

import (
	"chain"
)

// CallerTeller returns a GRC20 compatible teller that, at each write call,
// resolves the caller as rlm.Previous() — the realm that crossed into the
// caller. rlm must be the caller's own captured cur (asserted via
// rlm.IsCurrent() inside the Teller methods).
func (tok *Token) CallerTeller() Teller {
	if tok == nil {
		panic("Token cannot be nil")
	}

	return &fnTeller{
		accountFn: func(_ int, rlm realm) address {
			return rlm.Previous().Address()
		},
		Token: tok,
	}
}

// ReadonlyTeller is a GRC20 compatible teller that panics for any write operation.
func (tok *Token) ReadonlyTeller() Teller {
	if tok == nil {
		panic("Token cannot be nil")
	}

	return &fnTeller{
		accountFn: nil,
		Token:     tok,
	}
}

// RealmTeller returns a GRC20 compatible teller that will store the
// caller realm permanently. Calling anything through this teller will
// result in allowance or balance changes for the realm that initialized the teller.
// The initializer of this teller should usually never share the resulting Teller from
// this method except maybe for advanced delegation flows such as a DAO treasury
// management.
//
// rlm must be the caller's own captured cur (asserted via rlm.IsCurrent()).
// The address is frozen eagerly at construction.
func (tok *Token) RealmTeller(_ int, rlm realm) Teller {
	if tok == nil {
		panic("Token cannot be nil")
	}
	if !rlm.IsCurrent() {
		panic(ErrSpoofedRealm)
	}

	caller := rlm.Address()

	return &fnTeller{
		accountFn: func(_ int, _ realm) address {
			return caller
		},
		Token: tok,
	}
}

// RealmSubTeller is like RealmTeller but uses the provided slug to derive a
// subaccount.
//
// rlm must be the caller's own captured cur (asserted via rlm.IsCurrent()).
// The subaccount address is frozen eagerly at construction.
func (tok *Token) RealmSubTeller(_ int, rlm realm, slug string) Teller {
	if tok == nil {
		panic("Token cannot be nil")
	}
	if !rlm.IsCurrent() {
		panic(ErrSpoofedRealm)
	}

	account := accountSlugAddr(rlm.Address(), slug)

	return &fnTeller{
		accountFn: func(_ int, _ realm) address {
			return account
		},
		Token: tok,
	}
}

// ImpersonateTeller returns a GRC20 compatible teller that impersonates as a
// specified address. This allows operations to be performed as if they were
// executed by the given address, enabling the caller to manipulate tokens on
// behalf of that address.
//
// It is particularly useful in scenarios where a contract needs to perform
// actions on behalf of a user or another account, without exposing the
// underlying logic or requiring direct access to the user's account. The
// returned teller will use the provided address for all operations, effectively
// masking the original caller.
//
// This method should be used with caution, as it allows for potentially
// sensitive operations to be performed under the guise of another address.
func (ledger *PrivateLedger) ImpersonateTeller(addr address) Teller {
	if ledger == nil {
		panic("Ledger cannot be nil")
	}

	return &fnTeller{
		accountFn: func(_ int, _ realm) address {
			return addr
		},
		Token: ledger.token,
	}
}

// generic tellers methods.
//

func (ft *fnTeller) Transfer(_ int, rlm realm, to address, amount int64) error {
	if ft.accountFn == nil {
		return ErrReadonly
	}
	if !rlm.IsCurrent() {
		return ErrSpoofedRealm
	}
	caller := ft.accountFn(0, rlm)
	return ft.Token.ledger.Transfer(caller, to, amount)
}

func (ft *fnTeller) Approve(_ int, rlm realm, spender address, amount int64) error {
	if ft.accountFn == nil {
		return ErrReadonly
	}
	if !rlm.IsCurrent() {
		return ErrSpoofedRealm
	}
	caller := ft.accountFn(0, rlm)
	return ft.Token.ledger.Approve(caller, spender, amount)
}

func (ft *fnTeller) TransferFrom(_ int, rlm realm, owner, to address, amount int64) error {
	if ft.accountFn == nil {
		return ErrReadonly
	}
	if !rlm.IsCurrent() {
		return ErrSpoofedRealm
	}
	spender := ft.accountFn(0, rlm)
	return ft.Token.ledger.TransferFrom(owner, spender, to, amount)
}

// helpers
//

// accountSlugAddr returns the address derived from the specified address and slug.
func accountSlugAddr(addr address, slug string) address {
	// XXX: use a new `std.XXX` call for this.
	if slug == "" {
		return addr
	}
	key := addr.String() + "/" + slug
	return chain.PackageAddress(key) // temporarily using this helper
}

package grc20

import (
	"chain"
	"math"
	"math/overflow"
	"strconv"

	"gno.land/p/nt/ufmt/v0"
)

// NewToken creates a Token whose origRealm is bound to the calling realm.
// rlm must be the caller's own captured cur (asserted via rlm.IsCurrent()),
// and rlm.PkgPath() — the calling realm itself — becomes the Token's
// origRealm. Token.ID() returns origRealm + "." + symbol.
//
// Because IsCurrent runtime-validates that rlm came from the live
// crossing frame, origRealm is unforgeable: an external realm cannot
// fabricate a Token claiming to belong to a different package.
//
// Typical call from a realm's init(cur realm) or other crossing function:
//
//	Token, ledger := grc20.NewToken(0, cur, "Foo", "FOO", 4)
//
// If the Token should be discoverable, follow up with
// grc20reg.Register(cross, Token, slug).
func NewToken(_ int, rlm realm, name, symbol string, decimals int) (*Token, *PrivateLedger) {
	if !rlm.IsCurrent() {
		panic(ErrSpoofedRealm)
	}
	pkgPath := rlm.PkgPath()
	if pkgPath == "" {
		panic(ErrNotRealm)
	}
	if !validName(name) {
		panic(ErrInvalidName)
	}
	if !validSymbol(symbol) {
		panic(ErrInvalidSymbol)
	}
	if decimals < 0 || decimals > MaxDecimals {
		panic(ErrInvalidDecimals)
	}
	ledger := &PrivateLedger{}
	token := &Token{
		name:      name,
		symbol:    symbol,
		decimals:  decimals,
		origRealm: pkgPath,
		ledger:    ledger,
	}
	ledger.token = token
	return token, ledger
}

// validName reports whether name is a valid display name: non-empty,
// within MaxNameLen, and contains no control characters (any rune
// below 0x20 or 0x7f). Permits Unicode letters, digits, punctuation,
// and spaces — name is purely a display field.
func validName(name string) bool {
	if name == "" || len(name) > MaxNameLen {
		return false
	}
	for _, c := range name {
		if c < 0x20 || c == 0x7f {
			return false
		}
	}
	return true
}

// validSymbol reports whether symbol is a valid token symbol: non-empty,
// within MaxSymbolLen, and consists only of [A-Za-z0-9_-]. Matches
// grc20reg.validateSlug so the symbol round-trips cleanly through
// Token.ID() and any registry binding.
func validSymbol(symbol string) bool {
	if symbol == "" || len(symbol) > MaxSymbolLen {
		return false
	}
	for _, c := range symbol {
		if !isAlnum(c) && c != '_' && c != '-' {
			return false
		}
	}
	return true
}

func isAlnum(c rune) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
}

// GetName returns the name of the token.
func (tok Token) GetName() string { return tok.name }

// GetSymbol returns the symbol of the token.
func (tok Token) GetSymbol() string { return tok.symbol }

// GetDecimals returns the number of decimals used to get the token's precision.
func (tok Token) GetDecimals() int { return tok.decimals }

// TotalSupply returns the total supply of the token.
func (tok Token) TotalSupply() int64 { return tok.ledger.totalSupply }

// KnownAccounts returns the number of known accounts in the bank.
func (tok Token) KnownAccounts() int { return tok.ledger.balances.Size() }

// ID returns the Identifier of the token.
// It is composed of the original realm and the provided symbol.
func (tok *Token) ID() string {
	return tok.origRealm + "." + tok.symbol
}

// HasAddr checks if the specified address is a known account in the bank.
func (tok Token) HasAddr(addr address) bool {
	return tok.ledger.hasAddr(addr)
}

// BalanceOf returns the balance of the specified address.
func (tok Token) BalanceOf(addr address) int64 {
	return tok.ledger.balanceOf(addr)
}

// Allowance returns the allowance of the specified owner and spender.
func (tok Token) Allowance(owner, spender address) int64 {
	return tok.ledger.allowance(owner, spender)
}

func (tok Token) RenderHome() string {
	str := ""
	str += ufmt.Sprintf("# %s ($%s)\n\n", tok.name, tok.symbol)
	str += ufmt.Sprintf("* **Decimals**: %d\n", tok.decimals)
	str += ufmt.Sprintf("* **Total supply**: %d\n", tok.ledger.totalSupply)
	str += ufmt.Sprintf("* **Known accounts**: %d\n", tok.KnownAccounts())
	return str
}

// SpendAllowance decreases the allowance of the specified owner and spender.
func (led *PrivateLedger) SpendAllowance(owner, spender address, amount int64) error {
	if !owner.IsValid() || !spender.IsValid() {
		return ErrInvalidAddress
	}

	if amount < 0 {
		return ErrInvalidAmount
	}
	// do nothing
	if amount == 0 {
		return nil
	}

	currentAllowance := led.allowance(owner, spender)
	if currentAllowance < amount {
		return ErrInsufficientAllowance
	}

	key := allowanceKey(owner, spender)
	newAllowance := overflow.Sub64p(currentAllowance, amount)

	if newAllowance == 0 {
		led.allowances.Remove(key)
	} else {
		led.allowances.Set(key, newAllowance)
	}

	return nil
}

// Transfer transfers tokens from the specified from address to the specified to address.
func (led *PrivateLedger) Transfer(from, to address, amount int64) error {
	if !from.IsValid() {
		return ErrInvalidAddress
	}
	if !to.IsValid() {
		return ErrInvalidAddress
	}
	if from == to {
		return ErrCannotTransferToSelf
	}
	if amount < 0 {
		return ErrInvalidAmount
	}

	var (
		toBalance   = led.balanceOf(to)
		fromBalance = led.balanceOf(from)
	)

	if fromBalance < amount {
		return ErrInsufficientBalance
	}

	var (
		newToBalance   = overflow.Add64p(toBalance, amount)
		newFromBalance = overflow.Sub64p(fromBalance, amount)
	)

	led.balances.Set(string(to), newToBalance)

	if newFromBalance == 0 {
		led.balances.Remove(string(from))
	} else {
		led.balances.Set(string(from), newFromBalance)
	}

	chain.Emit(
		TransferEvent,
		"token", led.token.ID(),
		"from", from.String(),
		"to", to.String(),
		"value", strconv.Itoa(int(amount)),
	)

	return nil
}

// TransferFrom transfers tokens from the specified owner to the specified to address.
// It first checks if the owner has sufficient balance and then decreases the allowance.
func (led *PrivateLedger) TransferFrom(owner, spender, to address, amount int64) error {
	if amount < 0 {
		return ErrInvalidAmount
	}

	if !owner.IsValid() || !to.IsValid() {
		return ErrInvalidAddress
	}

	if led.balanceOf(owner) < amount {
		return ErrInsufficientBalance
	}

	// The check above guarantees that Transfer will succeed, ensuring
	// atomicity for the subsequent operations.
	if err := led.SpendAllowance(owner, spender, amount); err != nil {
		return err
	}

	if err := led.Transfer(owner, to, amount); err != nil {
		return err
	}

	return nil
}

// Approve sets the allowance of the specified owner and spender.
func (led *PrivateLedger) Approve(owner, spender address, amount int64) error {
	if !owner.IsValid() || !spender.IsValid() {
		return ErrInvalidAddress
	}
	if amount < 0 {
		return ErrInvalidAmount
	}

	led.allowances.Set(allowanceKey(owner, spender), amount)

	chain.Emit(
		ApprovalEvent,
		"token", led.token.ID(),
		"owner", string(owner),
		"spender", string(spender),
		"value", strconv.Itoa(int(amount)),
	)

	return nil
}

// Mint increases the total supply of the token and adds the specified amount to the specified address.
func (led *PrivateLedger) Mint(addr address, amount int64) error {
	if !addr.IsValid() {
		return ErrInvalidAddress
	}
	if amount < 0 {
		return ErrInvalidAmount
	}

	// limit amount to MaxInt64 - totalSupply
	if amount > overflow.Sub64p(math.MaxInt64, led.totalSupply) {
		return ErrMintOverflow
	}

	led.totalSupply += amount
	currentBalance := led.balanceOf(addr)
	newBalance := overflow.Add64p(currentBalance, amount)

	led.balances.Set(string(addr), newBalance)

	chain.Emit(
		TransferEvent,
		"token", led.token.ID(),
		"from", "",
		"to", string(addr),
		"value", strconv.Itoa(int(amount)),
	)

	return nil
}

// Burn decreases the total supply of the token and subtracts the specified amount from the specified address.
func (led *PrivateLedger) Burn(addr address, amount int64) error {
	if !addr.IsValid() {
		return ErrInvalidAddress
	}
	if amount < 0 {
		return ErrInvalidAmount
	}

	currentBalance := led.balanceOf(addr)
	if currentBalance < amount {
		return ErrInsufficientBalance
	}

	led.totalSupply = overflow.Sub64p(led.totalSupply, amount)
	newBalance := overflow.Sub64p(currentBalance, amount)

	if newBalance == 0 {
		led.balances.Remove(string(addr))
	} else {
		led.balances.Set(string(addr), newBalance)
	}

	chain.Emit(
		TransferEvent,
		"token", led.token.ID(),
		"from", string(addr),
		"to", "",
		"value", strconv.Itoa(int(amount)),
	)

	return nil
}

// hasAddr checks if the specified address is a known account in the ledger.
func (led PrivateLedger) hasAddr(addr address) bool {
	return led.balances.Has(addr.String())
}

// balanceOf returns the balance of the specified address.
func (led PrivateLedger) balanceOf(addr address) int64 {
	balance, found := led.balances.Get(addr.String())
	if !found {
		return 0
	}
	return balance.(int64)
}

// allowance returns the allowance of the specified owner and spender.
func (led PrivateLedger) allowance(owner, spender address) int64 {
	allowance, found := led.allowances.Get(allowanceKey(owner, spender))
	if !found {
		return 0
	}
	return allowance.(int64)
}

// allowanceKey returns the key for the allowance of the specified owner and spender.
func allowanceKey(owner, spender address) string {
	return owner.String() + ":" + spender.String()
}

package grc20

import (
	"errors"

	"gno.land/p/nt/avl/v0"
)

// Teller interface defines the methods that a GRC20 token must implement. It
// extends the TokenMetadata interface to include methods for managing token
// transfers, allowances, and querying balances.
//
// The Teller interface is designed to ensure that any token adhering to this
// standard provides a consistent API for interacting with fungible tokens.
//
// SECURITY: Transfer/Approve/TransferFrom take (_ int, rlm realm, ...), so
// handing a Teller value to untrusted code yields a capability token to
// whatever Transfer/Approve/TransferFrom impl that code dispatches into.
// Any /p/ or /r/ function that accepts a Teller as a parameter from external
// callers MUST type-assert against the canonical concrete type (*fnTeller)
// via IsCanonicalTeller and reject otherwise. An unexported-marker "seal"
// does NOT defend against this — see
// p/test/seal/filetests/z_seal_iface_embedding_filetest.gno
// for the realistic embedding-bypass attack. Reference impl for the
// canonical-allowlist pattern: p/jaekwon/allowancesender.
type Teller interface {
	// Returns the name of the token.
	GetName() string

	// Returns the symbol of the token, usually a shorter version of the
	// name.
	GetSymbol() string

	// Returns the decimals places of the token.
	GetDecimals() int

	// Returns the amount of tokens in existence.
	TotalSupply() int64

	// Returns the amount of tokens owned by `account`.
	BalanceOf(account address) int64

	// Moves `amount` tokens from the caller's account to `to`. rlm must
	// be the caller's own captured cur — verified via rlm.IsCurrent().
	//
	// Returns an error if the operation failed.
	Transfer(_ int, rlm realm, to address, amount int64) error

	// Returns the remaining number of tokens that `spender` will be
	// allowed to spend on behalf of `owner` through {transferFrom}. This is
	// zero by default.
	//
	// This value changes when {approve} or {transferFrom} are called.
	Allowance(owner, spender address) int64

	// Sets `amount` as the allowance of `spender` over the caller's tokens.
	//
	// Returns an error if the operation failed.
	//
	// IMPORTANT: Beware that changing an allowance with this method brings
	// the risk that someone may use both the old and the new allowance by
	// unfortunate transaction ordering. One possible solution to mitigate
	// this race condition is to first reduce the spender's allowance to 0
	// and set the desired value afterwards:
	// https://github.com/ethereum/EIPs/issues/20#issuecomment-263524729
	Approve(_ int, rlm realm, spender address, amount int64) error

	// Moves `amount` tokens from `from` to `to` using the
	// allowance mechanism. `amount` is then deducted from the caller's
	// allowance.
	//
	// Returns an error if the operation failed.
	TransferFrom(_ int, rlm realm, from, to address, amount int64) error
}

// Token represents a fungible token with a name, symbol, and a certain number
// of decimal places. It maintains a ledger for tracking balances and allowances
// of addresses.
//
// The Token struct provides methods for retrieving token metadata, such as the
// name, symbol, and decimals, as well as methods for interacting with the
// ledger, including checking balances and allowances.
type Token struct {
	// Name of the token (e.g., "Dummy Token").
	name string
	// Symbol of the token (e.g., "DUMMY").
	symbol string
	// Number of decimal places used for the token's precision.
	decimals int
	// Original realm of the token (e.g., "gno.land/r/demo/foo20").
	origRealm string
	// Pointer to the PrivateLedger that manages balances and allowances.
	ledger *PrivateLedger
}

// PrivateLedger is a struct that holds the balances and allowances for the
// token. It provides administrative functions for minting, burning,
// transferring tokens, and managing allowances.
//
// The PrivateLedger is not safe to expose publicly, as it contains sensitive
// information regarding token balances and allowances, and allows direct,
// unrestricted access to all administrative functions.
type PrivateLedger struct {
	// Total supply of the token managed by this ledger.
	totalSupply int64
	// chain.Address -> int64
	balances avl.Tree
	// owner.(chain.Address)+":"+spender.(chain.Address)) -> int64
	allowances avl.Tree
	// Pointer to the associated Token struct
	token *Token
}

var (
	ErrInsufficientBalance   = errors.New("insufficient balance")
	ErrInsufficientAllowance = errors.New("insufficient allowance")
	ErrInvalidAddress        = errors.New("invalid address")
	ErrCannotTransferToSelf  = errors.New("cannot send transfer to self")
	ErrReadonly              = errors.New("banker is readonly")
	ErrRestrictedTokenOwner  = errors.New("restricted to bank owner")
	ErrMintOverflow          = errors.New("mint overflow")
	ErrInvalidAmount         = errors.New("invalid amount")
	ErrSpoofedRealm          = errors.New("rlm does not match the current crossing frame")
	ErrNotRealm              = errors.New("rlm must be a realm (got EOA/origin)")
	ErrInvalidName           = errors.New("invalid token name (empty, too long, or contains control chars)")
	ErrInvalidSymbol         = errors.New("invalid token symbol (empty, too long, or contains chars outside [A-Za-z0-9_-])")
	ErrInvalidDecimals       = errors.New("invalid decimals (must be 0..18)")
)

// Construction limits. Symbol is restricted to the same charset as
// grc20reg.validateSlug because Token.ID() = origRealm + "." + symbol is
// emitted in events and frequently used as a registry slug; banning `.`
// `/` and whitespace here prevents downstream parsers from being fooled
// by ambiguous IDs (e.g. an attacker emitting tokens whose ID parses as
// belonging to a victim realm). Name is for display only and allows
// any valid UTF-8 except control characters.
const (
	MaxNameLen   = 64
	MaxSymbolLen = 11
	MaxDecimals  = 18
)

const (
	MintEvent     = "Mint"
	BurnEvent     = "Burn"
	TransferEvent = "Transfer"
	ApprovalEvent = "Approval"
)

type fnTeller struct {
	accountFn func(_ int, rlm realm) address
	*Token
}

var _ Teller = (*fnTeller)(nil)

// IsCanonicalTeller reports whether t is the canonical *fnTeller produced by
// Token.CallerTeller / RealmTeller / RealmSubTeller / ReadonlyTeller /
// ImpersonateTeller. Use this at any public entry point that accepts a
// Teller from an external caller before invoking its methods.
//
// Foreign types — including embedding-based wrappers like
// `type Evil struct { grc20.Teller }` — are rejected because type
// assertions are nominal: *Evil is not *fnTeller, regardless of method
// promotion. This is the reliable defense; the unexported-marker "seal"
// pattern is bypassable via embedding (see
// p/test/seal/filetests/z_seal_iface_embedding_filetest.gno).
//
// Mirrors the precedent of chain/banker.IsCanonical and
// p/jaekwon/allowancesender's canonical-impl check.
func IsCanonicalTeller(t Teller) bool {
	_, ok := t.(*fnTeller)
	return ok
}

// Package drop is the GNOMIES meme token, its genesis claim, and its GovDAO.
//
// Supply is 10_000_000_000 units (0 decimals: 1 unit = 1 GNOMIES).
//   - 87% airdrop, pro-rata to each wallet's genesis GNOT
//   - 10% liquidity, held here until a listing vote
//   - 3% community fund, plus the pro-rata remainder, held here until a spend vote
//
// A leaf is "g1...:<amount>". Claim pays that full amount once. The
// deployer sets the claim start. The window is 90 days. Unclaimed airdrop
// is burned. Each claim must attach exactly 1 GNOT. That GNOT stays in
// this realm. There is no withdraw. GNOT and liquidity tokens leave only
// through a passed listing vote. Community tokens leave only through a
// passed spend vote. The realm does not recompute GNOT weights.
package drop

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"crypto/merkle"
	"encoding/hex"
	"strconv"
	"time"

	"gno.land/p/g10u9x5yhwktwa6pwxv4nryp9h58duu7zf9r8q2h/grc20"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ownable/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	// TotalSupply is the whole GNOMIES mint. Decimals are 0.
	TotalSupply int64 = 10_000_000_000
	// CommunityBps is 3% of supply. The pro-rata remainder is added on top.
	CommunityBps int64 = 300
	// LiquidityBps is the single liquidity sleeve, 10% of supply.
	LiquidityBps int64 = 1_000
	// BpsBasis is 100%.
	BpsBasis int64 = 10_000

	// ClaimFee is the confirmation payment, 1 GNOT.
	ClaimFee int64 = 1_000_000
	// ClaimWindow is the claim period after the deployer-set start: 90 days.
	ClaimWindow int64 = 90 * 24 * 60 * 60
	// VoteWindow is how long a GovDAO proposal stays open.
	VoteWindow int64 = 7 * 24 * 60 * 60
	// quorumBps is the yes-vote floor, measured against the sealed airdrop budget.
	quorumBps int64 = 1_000

	KindSpend  = 1
	KindList   = 2
	KindSignal = 3

	maxProofAunts = 100
	hashLen       = 32
	maxMemo       = 240
)

type proposal struct {
	kind     int
	proposer address
	to       address
	tokenAmt int64
	gnotAmt  int64
	memo     string
	start    int64
	end      int64
	yes      int64
	no       int64
	executed bool
	passed   bool
}

var (
	token     *grc20.Token
	ledger    *grc20.PrivateLedger
	admin     *ownable.Ownable
	adminAddr address

	escrow address

	sealed        bool
	root          []byte
	eligible      int
	allocated     int64
	communityLeft int64
	liqLeft       int64
	airdropLeft   int64
	claimStart    int64
	claimFees     int64
	burned        bool

	claimed      avl.Tree
	proposals    avl.Tree
	votes        avl.Tree
	nextProposal int
)

// Init binds the deployer as admin. The community fund stays in this realm.
func Init(cur realm) {
	if token != nil {
		panic("already initialized")
	}
	mustUser(cur)
	mustNoPayment()
	caller := cur.Previous().Address()
	admin = ownable.NewWithAddress(caller)
	adminAddr = caller
	escrow = cur.Address()
	token, ledger = grc20.NewToken(0, cur, "Gnomies", "GNOMIES", 0)
	chain.Emit("Init", "admin", caller.String())
}

// TransferAdmin moves the admin seat. Admin cannot move funds.
func TransferAdmin(cur realm, next address) {
	mustAdmin(cur)
	mustNoPayment()
	if err := admin.TransferOwnership(0, cur, next); err != nil {
		panic(err.Error())
	}
	adminAddr = next
}

// Seal mints the whole supply and commits the eligible-set Merkle root.
// airdropTotal is the sum of the leaf amounts, at most the 87% pool.
// Integer dust is added to the community budget inside this realm.
func Seal(cur realm, rootHex string, eligibleCount int, airdropTotal int64) {
	mustAdmin(cur)
	mustNoPayment()
	if sealed {
		panic("already sealed")
	}
	if eligibleCount <= 0 {
		panic("eligible count")
	}
	decoded, err := hex.DecodeString(rootHex)
	if err != nil || len(decoded) != hashLen {
		panic("root")
	}
	communityAmt := TotalSupply * CommunityBps / BpsBasis
	liqAmt := TotalSupply * LiquidityBps / BpsBasis
	pool := TotalSupply - communityAmt - liqAmt
	if airdropTotal <= 0 || airdropTotal > pool {
		panic("allocated")
	}
	communityAmt += pool - airdropTotal

	mustMint(escrow, communityAmt+liqAmt+airdropTotal)

	root = append([]byte(nil), decoded...)
	eligible = eligibleCount
	allocated = airdropTotal
	communityLeft = communityAmt
	liqLeft = liqAmt
	airdropLeft = airdropTotal
	sealed = true

	chain.Emit(
		"Seal",
		"root", hex.EncodeToString(root),
		"eligible", strconv.Itoa(eligibleCount),
		"allocated", strconv.FormatInt(airdropTotal, 10),
		"community", strconv.FormatInt(communityAmt, 10),
		"liquidity", strconv.FormatInt(liqAmt, 10),
	)
}

// SetClaimStart opens claims at start (unix seconds). The deployer may
// call it once. start must be in the future. Claims run for ClaimWindow.
func SetClaimStart(cur realm, start int64) {
	mustAdmin(cur)
	mustNoPayment()
	if !sealed {
		panic("not sealed")
	}
	if claimStart != 0 {
		panic("claim start set")
	}
	if start <= time.Now().Unix() {
		panic("claim start")
	}
	claimStart = start
	chain.Emit(
		"SetClaimStart",
		"start", strconv.FormatInt(start, 10),
		"end", strconv.FormatInt(start+ClaimWindow, 10),
	)
}

// Claim pays the caller's full sealed amount. Attach exactly 1 GNOT.
// That GNOT remains in this realm. There is no withdraw.
func Claim(cur realm, index int, amount int64, auntsHex string) {
	mustUser(cur)
	if !sealed {
		panic("not sealed")
	}
	if !claimOpen() {
		panic("claim closed")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent.AmountOf("ugnot") != ClaimFee {
		panic("claim fee")
	}
	if amount <= 0 || amount > allocated {
		panic("amount")
	}
	caller := cur.Previous().Address()
	key := caller.String()
	if index < 0 || index >= eligible {
		panic("index")
	}
	aunts, err := hex.DecodeString(auntsHex)
	if err != nil || len(aunts)%hashLen != 0 || len(aunts)/hashLen > maxProofAunts {
		panic("bad proof")
	}
	if !merkle.VerifySimpleProof(root, leafData(key, amount), index, eligible, aunts) {
		panic("bad proof")
	}
	if claimed.Has(key) {
		panic("already claimed")
	}
	if airdropLeft < amount {
		panic("airdrop empty")
	}
	airdropLeft -= amount
	claimFees += ClaimFee
	claimed.Set(key, amount)
	mustTransfer(escrow, caller, amount)
	chain.Emit(
		"Claim",
		"to", key,
		"index", strconv.Itoa(index),
		"amount", strconv.FormatInt(amount, 10),
	)
}

// BurnUnclaimed destroys the airdrop budget still here after the window.
// Anyone may call it. A second call reverts. GovDAO cannot recover it.
func BurnUnclaimed(cur realm) {
	if cur.Address() != escrow {
		panic("escrow")
	}
	mustNoPayment()
	if !sealed {
		panic("not sealed")
	}
	if burned {
		panic("already burned")
	}
	if claimStart == 0 || time.Now().Unix() < claimStart+ClaimWindow {
		panic("claim open")
	}
	left := airdropLeft
	airdropLeft = 0
	burned = true
	if left > 0 {
		mustBurn(escrow, left)
	}
	chain.Emit("BurnUnclaimed", "amount", strconv.FormatInt(left, 10))
}

// Propose opens a GovDAO vote. kind is KindSpend, KindList, or KindSignal.
// The caller must already hold GNOMIES. Claims must have started.
func Propose(cur realm, kind int, to address, tokenAmt int64, gnotAmt int64, memo string) int {
	mustUser(cur)
	mustNoPayment()
	if !claimsStarted() {
		panic("claim not started")
	}
	caller := cur.Previous().Address()
	if BalanceOf(caller) <= 0 {
		panic("proposer")
	}
	switch kind {
	case KindSpend:
		if memo != "" || gnotAmt != 0 {
			panic("proposal")
		}
		if !to.IsValid() || to == escrow || tokenAmt <= 0 || tokenAmt > communityLeft {
			panic("proposal")
		}
	case KindList:
		if memo != "" {
			panic("proposal")
		}
		if !to.IsValid() || to == escrow || tokenAmt <= 0 || tokenAmt > liqLeft || gnotAmt <= 0 {
			panic("proposal")
		}
	case KindSignal:
		if to.IsValid() || tokenAmt != 0 || gnotAmt != 0 {
			panic("proposal")
		}
		if len(memo) == 0 || len(memo) > maxMemo {
			panic("proposal")
		}
	default:
		panic("proposal")
	}
	now := time.Now().Unix()
	id := nextProposal
	nextProposal++
	proposals.Set(strconv.Itoa(id), &proposal{
		kind:     kind,
		proposer: caller,
		to:       to,
		tokenAmt: tokenAmt,
		gnotAmt:  gnotAmt,
		memo:     memo,
		start:    now,
		end:      now + VoteWindow,
	})
	chain.Emit(
		"Propose",
		"id", strconv.Itoa(id),
		"kind", strconv.Itoa(kind),
		"proposer", caller.String(),
	)
	return id
}

// Vote records the caller's current GNOMIES balance as yes or no.
// One vote per address. Moving tokens after voting does not remove that weight.
func Vote(cur realm, id int, yes bool) {
	mustUser(cur)
	mustNoPayment()
	p := proposalOf(id)
	now := time.Now().Unix()
	if now < p.start || now >= p.end {
		panic("voting")
	}
	caller := cur.Previous().Address()
	key := voteKey(id, caller)
	if votes.Has(key) {
		panic("voted")
	}
	weight := BalanceOf(caller)
	if weight <= 0 {
		panic("vote weight")
	}
	votes.Set(key, yes)
	if yes {
		p.yes += weight
	} else {
		p.no += weight
	}
	proposals.Set(strconv.Itoa(id), p)
	chain.Emit(
		"Vote",
		"id", strconv.Itoa(id),
		"voter", caller.String(),
		"weight", strconv.FormatInt(weight, 10),
	)
}

// Execute closes a finished proposal. A passed spend or listing moves
// only the budget that kind is allowed to move. A failed vote moves nothing.
func Execute(cur realm, id int) {
	mustNoPayment()
	if cur.Address() != escrow {
		panic("escrow")
	}
	p := proposalOf(id)
	if p.executed {
		panic("executed")
	}
	if time.Now().Unix() < p.end {
		panic("voting")
	}
	passed := p.yes > p.no && p.yes >= Quorum()
	if passed && !executable(p) {
		passed = false
	}
	p.executed = true
	p.passed = passed
	proposals.Set(strconv.Itoa(id), p)
	if !passed {
		chain.Emit("Reject", "id", strconv.Itoa(id))
		return
	}
	switch p.kind {
	case KindSpend:
		communityLeft -= p.tokenAmt
		mustTransfer(escrow, p.to, p.tokenAmt)
	case KindList:
		liqLeft -= p.tokenAmt
		mustTransfer(escrow, p.to, p.tokenAmt)
		sendGnot(cur, p.to, p.gnotAmt)
	case KindSignal:
	default:
		panic("proposal")
	}
	chain.Emit("Execute", "id", strconv.Itoa(id), "kind", strconv.Itoa(p.kind))
}

